/** Viewer obstacle kind -> TTS obstacle family. blaze has no TTS scan. */
export const OBSTACLE_FAMILY: Record<string, string | null> = {
  "asteroid": "asteroid",
  "debris": "debris_cloud",
  "gas": "gas_cloud",
  "other": "electro_chaff_cloud",
  "loose-cargo": "loose_cargo",
  "spare-parts": "loose_cargo",
  "blaze": null
};

export function obstacleArt(kind: string, index = 0): ObstacleArt | null {
  const family = OBSTACLE_FAMILY[kind];
  if (!family) return null;
  const list = ART[family];
  if (!list || list.length === 0) return null;
  return list[((index % list.length) + list.length) % list.length];
}

/** Alias used by Board.svelte. */
export const obstacleSprite = obstacleArt;
